import androidx.compose.material.pullrefresh.pullRefresh
import androidx.compose.material.pullrefresh.rememberPullRefreshState

@Composable
fun ListsScreen(
    onNavigateToListDetail: (ShoppingList) -> Unit = {}
) {
    var showCreateModal by remember { mutableStateOf(false) }
    var showDeleteConfirmation by remember { mutableStateOf(false) }
    var listToDelete by remember { mutableStateOf<ShoppingList?>(null) }

    val lists by ShoppingListService.listsState.collectAsState()
    val scope = rememberCoroutineScope()

    var isRefreshing by remember { mutableStateOf(false) }
    val refreshState = rememberPullRefreshState(
        refreshing = isRefreshing,
        onRefresh = {
            scope.launch {
                isRefreshing = true
                ShoppingListService.refreshLists()
                isRefreshing = false
            }
        }
    )

    // Al entrar en la pantalla, cargar listas desde la API
    LaunchedEffect(Unit) {
        ShoppingListService.refreshLists()
    }

    Scaffold(
        floatingActionButton = {
            FloatingActionButton(
                onClick = { showCreateModal = true },
                containerColor = Secondary,
                contentColor = Color.White,
                shape = CircleShape
            ) {
                Icon(Icons.Filled.Add, "Crear nueva lista")
            }
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .pullRefresh(refreshState)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 24.dp)
            ) {
                // Título, alineado con Products y Profile
                Text(
                    text = "Listas",
                    style = MaterialTheme.typography.headlineMedium,
                    fontWeight = androidx.compose.ui.text.font.FontWeight.Bold,
                    modifier = Modifier
                        .align(Alignment.Start)
                        .padding(vertical = 16.dp) // sin padding extra superior
                )

                if (lists.isEmpty()) {
                    EmptyStateListas()
                } else {
                    ListsGrid(
                        lists = lists,
                        onListClick = { list -> onNavigateToListDetail(list) },
                        onToggleFavorite = { /* TODO implementar favorito */ },
                        onDeleteList = { list ->
                            listToDelete = list
                            showDeleteConfirmation = true
                        }
                    )
                }
            }

            PullRefreshIndicator(
                refreshing = isRefreshing,
                state = refreshState,
                modifier = Modifier
                    .align(Alignment.TopCenter)
            )
        }
    }

    // Modal para crear lista
    if (showCreateModal) {
        CreateListModal(
            onDismiss = { showCreateModal = false },
            onCreateList = { name, image ->
                scope.launch {
                    ShoppingListService.createList(name, image)
                    // opcional: refrescar si la API añade más datos
                    // ShoppingListService.refreshLists()
                }
                showCreateModal = false
            }
        )
    }

    // Modal de confirmación para eliminar
    if (showDeleteConfirmation && listToDelete != null) {
        ConfirmationModal(
            title = "Eliminar Lista",
            message = "¿Estás seguro de que deseas eliminar la lista \"${listToDelete?.name}\"? Esta acción no se puede deshacer.",
            onDismiss = {
                showDeleteConfirmation = false
                listToDelete = null
            },
            onConfirm = {
                listToDelete?.let { list ->
                    scope.launch {
                        ShoppingListService.deleteList(list.id)
                        // ShoppingListService.refreshLists()
                    }
                }
                showDeleteConfirmation = false
                listToDelete = null
            }
        )
    }
}

